class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [make_task(id=i, title=f"Task {i}") for i in range(1, 6)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2), FIXED_NOW)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=3), FIXED_NOW)
        assert len(page.items) == 2
        assert page.offset == 3

    def test_offset_past_end(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=10), FIXED_NOW)
        assert len(page.items) == 0
        assert page.total == 5
        assert page.has_more is False

    def test_limit_larger_than_total(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=100), FIXED_NOW)
        assert len(page.items) == 5
        assert page.has_more is False

"""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags

from conftest import make_task


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3

    def test_add_and_get(self, repo):
        task = make_task(id=1)
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        task = make_task(id=1)
        repo.add(task)
        with pytest.raises(ValueError, match="already exists"):
            repo.add(make_task(id=1))

    def test_list_returns_snapshot(self, repo):
        repo.add(make_task(id=1))
        repo.add(make_task(id=2))
        result = repo.list()
        assert len(list(result)) == 2

    def test_update(self, repo):
        task = make_task(id=1, title="Before")
        repo.add(task)
        updated = make_task(id=1, title="After")
        repo.update(updated)
        assert repo.get(1).title == "After"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=999))

    def test_delete_existing(self, repo):
        repo.add(make_task(id=1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("hello"), Tag("HELLO")])
        assert len(result) == 1
        assert result[0].name == "hello"

    def test_accepts_strings(self):
        result = normalize_tags(["alpha", "Beta"])
        assert [t.name for t in result] == ["alpha", "beta"]

    def test_mixed_tags_and_strings(self):
        result = normalize_tags([Tag("one"), "two"])
        assert len(result) == 2

    def test_empty_input(self):
        assert normalize_tags([]) == []

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["z", "a", "m"])
        assert [t.name for t in result] == ["z", "a", "m"]

